}
export function test(): null {
  let total: int = 0;
  let i: int = 0;
  while (i < 5) {
    i = i + 1;
    if (i === 3) { continue; }
    total = total + i;
  }
  for (let j: int = 0; j < 3; j = j + 1) {
    if (j === 2) { break; }
    total = total + 10;
  }
  let c: int = classify(-5) * 100 + classify(0) * 10 + classify(7);
  if (c === 12 && total === 32) {
    console.log("control-flow-ok");
  } else {
    console.log("control-flow-broken");
