export class U {
  name: string = "";
  nick?: string | null;
  age: int = 0;
}
export function test(): int {
  let u: U = { name: "Ada", nick: null, age: 36 };
  let json: string = U$toJson(u);
  let v: U | null = U$fromJson(json);
  if (v !== null) {
    if (v.name === "Ada" && v.nick === null && v.age === 36) {
      let round: string = U$toJson(v);
      let w: U | null = U$fromJson(round);
      if (w !== null) {
        if (w.name === "Ada" && w.nick === null && w.age === 36) { return 1; }
      }
    }
  }
  return 0;
}

